import Foundation

/// A supplied user confirmation, never generated by the vision model. This
/// developer import is explicitly invoked for a confirmed saved-video label.
struct ConfirmedVideoActivity: Decodable {
    let confirmationID: UUID
    let videoID: String
    let kind: ActivityKind
    let entity: String
    let location: String
    let summary: String
    let startSeconds: Double
    let endSeconds: Double

    func event(for job: VideoIndexJob) throws -> ActivityEvent {
        guard job.id == videoID, !job.isDemoVideo,
              !entity.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty, entity.count <= 120,
              !location.isEmpty, location.count <= 240, !summary.isEmpty, summary.count <= 700,
              startSeconds.isFinite, endSeconds.isFinite,
              startSeconds >= 0, endSeconds >= startSeconds, endSeconds <= job.duration else {
            throw GremmaError.message("The confirmed label does not match this saved video.")
        }
        let segment = "\(videoID):user-confirmed:\(confirmationID.uuidString)"
        return ActivityEvent(id: segment + ":event", videoID: videoID, segmentID: segment,
            kind: kind, entity: entity, location: location, summary: summary,
            occurredAt: job.recordedAt?.addingTimeInterval(endSeconds),
            startSeconds: startSeconds, endSeconds: endSeconds,
            confidence: 1, isUncertain: false, source: .userConfirmed)
    }
}
